head.script:
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 displayValueOnUseFilterList 를 확인한다.
    //1. In the Source tab, check the displayValueOnUseFilterList.
    //Verify step 1. displayValueOnUseFilterList = "true"
    //Test step 2. 브라우저에서 임의로 필터를 설정한다. 
    //2. Set the filter arbitrarily in the browser.
    //Verify step 2. An arbitrarily selected filter is applied.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column9_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_customFilter_list').getElementsByTagName('div')[1].getElementsByTagName('input')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_customFilter_list').getElementsByTagName('div')[2].getElementsByTagName('input')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').textContent == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 브라우저에서 임의로 필터를 설정한다. 
    //2. Set the filter arbitrarily in the browser.
    //Verify step 2. An arbitrarily selected filter is applied.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column9_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column9_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_customFilter_list').getElementsByTagName('div')[1].getElementsByTagName('input')[0].checked", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dst_scrnItmTypCd.setData(['a', '1', 'b', '2']);
    dataList1.setData(["1", "2", "3", "4", "2", "6", "7", "1", "9"]);
    gridView1.setCellReadOnly(0, 0, true);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 28-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
